            />
            {showDateError && dateIsFuture && <div className="field-required">That day hasn&apos;t happened yet! Pick an earlier one?</div>}
          </div>
          <div className={'pc-field' + (showBalanceError && balanceEmpty ? ' field-error' : '')}>
